    17	/**
    18	 * Wizard state (ADR-0003). Holds the raw editing values of step 1 for one country, written to
    19	 * `sessionStorage` on every change, and the typed output that exists only after a valid
    20	 * "Continuar". Values are never logged. When storage is unavailable the state lives in memory.
    21	 */
    22	@Injectable({ providedIn: 'root' })
    23	export class QuoteStore {
    24	  private readonly clock = inject(CLOCK);
    25	  private readonly countrySignal = signal<string | null>(null);
    26	  private readonly valuesSignal = signal<RawValues>({});
    27	  private readonly outputSignal = signal<Step1Output | null>(null);
    28	  private readonly planSignal = signal<ChosenPlan | null>(null);
    29	  private warnedAboutStorage = false;
    30	
    31	  readonly country = this.countrySignal.asReadonly();
    32	  readonly values = this.valuesSignal.asReadonly();
    33	  readonly step1Output = this.outputSignal.asReadonly();
    34	  /** The chosen plan: its key only, never names or prices (ADR-0003, US-02-BR-07). */
    35	  readonly plan = this.planSignal.asReadonly();
