    37	  constructor() {
    38	    this.restore();
    39	  }
    40	
    41	  /** Enters a supported country's context; another country's stored state is discarded. */
    42	  enterCountry(code: string): void {
    43	    if (this.countrySignal() !== code) {
    44	      this.valuesSignal.set({});
    45	      this.outputSignal.set(null);
    46	      this.planSignal.set(null);
    47	      this.countrySignal.set(code);
    48	      this.clearStorage();
    49	    }
    50	    this.persist();
    51	  }
    52	
    53	  /**
    54	   * Closes the quote after a successful payment (ADR-0003, US-03-BR-06): the entry is removed and
    55	   * the in-memory country, values, typed output and plan are reset, so a reload or a back action
    56	   * leads to an empty step 1.
    57	   */
    58	  clearQuote(): void {
    59	    this.countrySignal.set(null);
    60	    this.valuesSignal.set({});
    61	    this.outputSignal.set(null);
    62	    this.planSignal.set(null);
    63	    this.clearStorage();
    64	  }
    65	
    66	  setValue(key: string, value: RawValue): void {
    67	    this.valuesSignal.update((values) => ({ ...values, [key]: value }));
    68	    this.outputSignal.set(null);
    69	    this.persist();
    70	  }
    71	
    72	  /** Chooses a plan, replacing any earlier choice; written to storage at once. */
    73	  choosePlan(key: string): void {
    74	    this.planSignal.set({ key });
    75	    this.persist();
    76	  }
    77	
    78	  /** Clears the choice when its key is not among the plans offered in this page load. */
    79	  prunePlan(offeredKeys: readonly string[]): void {
    80	    const chosen = this.planSignal();
    81	    if (chosen && !offeredKeys.includes(chosen.key)) {
    82	      this.planSignal.set(null);
    83	      this.persist();
    84	    }
    85	  }
    86	
    87	  /** Drops values of keys no longer configured and clears select values whose option is gone. */
    88	  prune(configs: FieldConfig[]): void {
    89	    const pruned: RawValues = {};
    90	    for (const [key, value] of Object.entries(this.valuesSignal())) {
    91	      const config = configs.find((c) => c.key === key);
    92	      if (!config) continue;
    93	      const optionGone = config.type === 'select' && typeof value === 'string' && value !== '' && !config.options?.some((o) => o.value === value);
    94	      pruned[key] = optionGone ? '' : value;
    95	    }
    96	    this.valuesSignal.set(pruned);
    97	    this.persist();
    98	  }
    99	
   100	  /** True when the stored values are valid for the given configuration, on the clock's today. */
   101	  isStep1Valid(configs: FieldConfig[]): boolean {
   102	    const model = hydrate(configs, this.valuesSignal());
   103	    return Object.keys(validateForm(configs, model, this.clock())).length === 0;
   104	  }
   105	
   106	  /** The typed output, only when every field is valid; otherwise `null` and no output is kept. */
   107	  completeStep1(configs: FieldConfig[]): Step1Output | null {
   108	    const country = this.countrySignal();
   109	    if (country === null || !this.isStep1Valid(configs)) {
   110	      this.outputSignal.set(null);
   111	      return null;
   112	    }
   113	    const output: Step1Output = { country, values: toOutput(configs, hydrate(configs, this.valuesSignal())) };
   114	    this.outputSignal.set(output);
   115	    return output;
   116	  }
   117	
   118	  private restore(): void {
   119	    let raw: string | null;
   120	    try {
   121	      raw = sessionStorage.getItem(STORAGE_KEY);
   122	    } catch {
   123	      this.warnStorageOnce();
   124	      return;
   125	    }
   126	    if (raw === null) return;
   127	    const entry = this.parseEntry(raw);
   128	    if (entry === null) {
   129	      console.warn('quote-wizard: the stored entry is invalid and was discarded');
   130	      this.clearStorage();
   131	      return;
   132	    }
   133	    this.countrySignal.set(entry.country);
   134	    this.valuesSignal.set(entry.values);
   135	    this.planSignal.set(entry.plan);
   136	  }
   137	
   138	  private parseEntry(raw: string): { country: string; values: RawValues; plan: ChosenPlan | null } | null {
   139	    let parsed: unknown;
   140	    try {
   141	      parsed = JSON.parse(raw);
   142	    } catch {
   143	      return null;
   144	    }
   145	    if (!isRecord(parsed) || parsed['version'] !== VERSION) return null;
   146	    const country = parsed['country'];
   147	    if (typeof country !== 'string' || !/^[A-Z]{2}$/.test(country)) return null;
   148	    const step1 = parsed['step1'];
   149	    if (!isRecord(step1)) return null;
   150	    const stored = step1['values'];
   151	    if (!isRecord(stored)) return null;
   152	    const values: RawValues = {};
   153	    for (const [key, value] of Object.entries(stored)) {
   154	      if (typeof value !== 'string' && typeof value !== 'boolean') return null;
   155	      values[key] = value;
   156	    }
   157	    const plan = parsed['plan'];
   158	    if (plan === undefined || plan === null) return { country, values, plan: null };
   159	    if (!isRecord(plan) || typeof plan['key'] !== 'string') return null;
   160	    return { country, values, plan: { key: plan['key'] } };
   161	  }
   162	
   163	  private persist(): void {
   164	    const country = this.countrySignal();
   165	    if (country === null) return;
   166	    const plan = this.planSignal();
