   185	  private warnStorageOnce(): void {
   186	    if (this.warnedAboutStorage) return;
   187	    this.warnedAboutStorage = true;
   188	    console.warn('quote-wizard: sessionStorage is unavailable, the state is kept in memory only');
   189	  }
   190	}
